import { jsonData, jsonError, readJson, validateCreateVendor } from '@/lib/domain'
import { requireUser } from '@/lib/supabase/server'

export async function GET() { try { const { supabase, user } = await requireUser(); const { data, error } = await supabase.from('vendors').select('*').eq('user_id', user.id).order('created_at', { ascending: false }); if (error) throw error; return jsonData((data || []).map((vendor) => ({ ...vendor, contact: typeof vendor.contact === 'object' && vendor.contact !== null ? vendor.contact : { name: vendor.contact || '', phone: vendor.phone || '', email: '', notes: '' } }))) } catch (error) { return jsonError(error instanceof Error ? error.message : 'Gagal memuat vendor.', 401) } }
export async function POST(request: Request) { try { const input = validateCreateVendor(await readJson(request)); const { supabase, user } = await requireUser(); const contact = { name: input.contactName || input.contact || '', phone: input.phone || '', email: input.email || '', notes: input.notes || '' }; const { data: vendor, error } = await supabase.from('vendors').insert({ user_id: user.id, name: input.name, category: input.category, contact, phone: contact.phone }).select().single(); if (error) throw error; await supabase.from('activity_logs').insert({ user_id: user.id, action: 'vendor.created', metadata: { vendorId: vendor.id, name: vendor.name } }); return jsonData(vendor, 201) } catch (error) { return jsonError(error instanceof Error ? error.message : 'Gagal membuat vendor.', 400) } }
